def doc(name):
    d=Document(O/'source'/name)
    for el in list(d._element.body):
        if el.tag!=qn('w:sectPr'):d._element.body.remove(el)
    sec=d.sections[0];sec.page_width=Mm(210);sec.page_height=Mm(297)
    sec.top_margin=Mm(17);sec.bottom_margin=Mm(17);sec.left_margin=Mm(19);sec.right_margin=Mm(19)
    for sty in ['Normal','Title','Heading 1','Heading 2']:
        st=d.styles[sty];st.font.name='Arial';st.font.color.rgb=RGBColor.from_string('252A30');st.font.size=Pt(10.5 if sty=='Normal'else 18 if sty=='Title'else 12)
        st.paragraph_format.space_after=Pt(5);st.paragraph_format.line_spacing=1.05
        if st._element.pPr is not None:
            for e in list(st._element.pPr):
                if e.tag==qn('w:pBdr'):st._element.pPr.remove(e)
    for hf in [sec.header,sec.footer]:
        for e in list(hf._element):hf._element.remove(e)
    h=sec.header.add_paragraph('НА СТОРОНЕ ПОДРЯДЧИКА');h.runs[0].font.size=Pt(8);h.runs[0].font.color.rgb=RGBColor.from_string('656B72')
    f=sec.footer.add_paragraph('nastoronepodryadchika.ru  |  nastoronepodryadchika@yandex.ru')
    f.runs[0].font.size=Pt(8);f.runs[0].font.color.rgb=RGBColor.from_string('656B72')
    return d
def para(d,text,bold=False):
    p=d.add_paragraph(text);p.paragraph_format.widow_control=True
    if bold:p.runs[0].bold=True
    return p
pending_page=set()
def heading(d,t):
    p=d.add_paragraph(t,'Heading 1')
    if id(d)in pending_page:p.paragraph_format.page_break_before=True;pending_page.remove(id(d))
    return p
def title(d,t):return d.add_paragraph(t,'Title')
def link(d,key):
    text,url=S[key];p=d.add_paragraph();h=OxmlElement('w:hyperlink');h.set(qn('r:id'),p.part.relate_to(url,RT.HYPERLINK,is_external=True));r=OxmlElement('w:r');pr=OxmlElement('w:rPr');c=OxmlElement('w:color');c.set(qn('w:val'),'72552B');pr.append(c);sz=OxmlElement('w:sz');sz.set(qn('w:val'),'19');pr.append(sz);r.append(pr);t=OxmlElement('w:t');t.text=text;r.append(t);h.append(r);p._p.append(h);return p
